// Incoming from FastAPI: { run_id, portfolio_id, metrics, holdings_snapshot }
const data = $input.first().json;
const holdings = data.holdings_snapshot || [];
const metrics = data.metrics || {};

// Group holdings by marketplace
const byMarket = {};
for (const h of holdings) {
  const mkt = h.marketplace || 'US';
  if (!byMarket[mkt]) byMarket[mkt] = [];
  byMarket[mkt].push(h);
}

// Market-specific risk notes
const marketRiskNotes = {
  US:  'Subject to SEC regulations, USD-denominated, EDGAR filing transparency.',
  IN:  'Subject to SEBI regulations, INR-denominated, BSE/NSE circuit breakers apply.',
  UK:  'Subject to FCA regulations, GBP-denominated, London Stock Exchange rules.',
  EU:  'Subject to ESMA/MiFID II, EUR-denominated, cross-border regulatory complexity.',
  HK:  'Subject to SFC regulations, HKD-denominated, China policy overhang risk.',
  JP:  'Subject to FSA regulations, JPY-denominated, BoJ policy sensitivity.',
};

const marketSummaryLines = Object.entries(byMarket).map(([mkt, hs]) => {
  const tickers = hs.map(h => `${h.ticker_symbol} (${h.exchange})`).join(', ');
  const risk = marketRiskNotes[mkt] || `${mkt} market — check local regulatory framework.`;
  return `**${mkt}**: ${tickers}\n  Risk context: ${risk}`;
}).join('\n\n');

const sectorLines = Object.entries(metrics.sector_exposure || {})
  .sort((a, b) => b[1] - a[1])
  .map(([s, w]) => `  - ${s}: ${(w * 100).toFixed(1)}%`)
  .join('\n');

const holdingLines = holdings.map(h =>
  `| ${h.ticker_symbol} | ${h.marketplace} | ${h.exchange} | ${h.quantity} | $${parseFloat(h.buy_price).toFixed(2)} |`
).join('\n');

const totalReturn = metrics.portfolio_total_return != null
  ? `${(metrics.portfolio_total_return * 100).toFixed(2)}%`
  : 'N/A (insufficient price data)';

const prompt = `You are a senior investment research analyst. Produce a rigorous research report for the portfolio below.

## Holdings
| Ticker | Market | Exchange | Qty | Buy Price |
|--------|--------|----------|-----|-----------|
${holdingLines}

## Market Exposure
${marketSummaryLines}

## Sector Exposure
${sectorLines || '  - Data unavailable'}

## Portfolio Metrics
- Total Return (since inception): ${totalReturn}
- Benchmark comparison: ${JSON.stringify(metrics.benchmark_comparison || {})}

---

Provide the following sections in markdown:

### 1. Executive Summary
One paragraph: portfolio style, market diversity, overall risk posture.

### 2. Market-by-Market Analysis
For EACH market in the portfolio:
- Holdings overview
- Market-specific risks (regulatory, currency, liquidity)
- Key events to monitor

### 3. Sector Concentration
Highlight overweights, underweights, and diversification quality.

### 4. Top 3 Research Priorities
Which holdings need immediate deeper research and why.

### 5. Risk Summary
Key risks ranked by severity. Include currency risk if multi-market portfolio.

Be specific and data-driven. Use numbers from the metrics provided.`;

return [{
  json: {
    run_id: data.run_id,
    portfolio_id: data.portfolio_id,
    metrics: metrics,
    holdings_snapshot: holdings,
    markets: Object.keys(byMarket),
    holdings_count: holdings.length,
    is_multi_market: Object.keys(byMarket).length > 1,
    claude_prompt: prompt,
  }
}];

const data = $input.first().json;

// Claude response shape: { content: [{ type: 'text', text: '...' }] }
const content = data.content;
let reportMd = '';

if (Array.isArray(content)) {
  reportMd = content
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('\n');
} else {
  reportMd = '# Research Report\n\nUnable to parse Claude response.';
}

// Pass through context fields for the completion step
const ctx = $('Prepare Context').first().json;

return [{
  json: {
    run_id: ctx.run_id,
    report_md: reportMd,
    metrics_json: ctx.metrics,
    markets: ctx.markets,
    holdings_count: ctx.holdings_count,
    is_multi_market: ctx.is_multi_market,
    status: 'COMPLETED',
  }
}];

const ctx = $('Prepare Context').first().json;
const claudeData = $('Claude Research Call').first().json;

let errorMsg = 'Claude API call failed';
if (claudeData && claudeData.error) {
  errorMsg = JSON.stringify(claudeData.error);
} else if (claudeData && claudeData.message) {
  errorMsg = claudeData.message;
}

return [{
  json: {
    run_id: ctx.run_id,
    error_type: 'LLM_ERROR',
    message: errorMsg,
  }
}];
